const vm=require('node:vm'),fs=require('node:fs'),assert=require('node:assert/strict');
const elements=new Map(),noop=()=>{};
function el(id){if(!elements.has(id))elements.set(id,{value:id==='#golden-receiver'?'1':'club',textContent:'',setAttribute(name,value){this[name]=value},classList:{add:noop,remove:noop,toggle:noop},style:{},firstChild:{style:{}},getBoundingClientRect:()=>({width:1280,height:720}),getContext:()=>({setTransform:noop}),focus:noop,showModal:noop,close:noop});return elements.get(id);}
let seed=771;const math=Object.create(Math);math.random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
const box={document:{querySelector:el,querySelectorAll:()=>[]},window:{},devicePixelRatio:1,addEventListener:noop,requestAnimationFrame:noop,console,Math:math,assert};vm.createContext(box);vm.runInContext(fs.readFileSync('web/i18n.js','utf8'),box);vm.runInContext(fs.readFileSync('web/game.js','utf8'),box);
function run(name,src){try{vm.runInContext("{"+src+"}",box);console.log('PASS',name)}catch(e){console.error('FAIL',name);throw e;}}
run('best of three defaults, configurable durations, golden point and deciding game',`defaultMatchGames=3;newMatch();assert.equal(matchGames,3);score=[3,3];assert.equal(awardPoint(0),'GAME');assert.equal(games[0],1);games=[1,1];score=[3,3];state='play';point(1,'WINNER');assert.equal(state,'over');assert.equal(games[1],2);assert.equal(sets[0]+sets[1],0);for(const n of [5,9]){defaultMatchGames=n;newMatch();games=[Math.floor(n/2),Math.floor(n/2)];score=[3,3];state='play';point(0,'WINNER');assert.equal(state,'over');assert.equal(games[0],Math.floor(n/2)+1);}defaultMatchGames=3;newMatch();defaultMatchGames=9;assert.equal(matchGames,3);defaultMatchGames=3;`);
run('new point starts with visible serve then rally',`newMatch();assert.equal(state,'serve');assert.equal(serverIndex,2);assert.equal(serveAttempt,1);for(let i=0;i<220;i++)tick(1/120);assert.equal(state,'play');assert(ball.serve);assert.equal(ball.receiverLane,1);`);
run('first fault preserves score, double fault awards exactly once',`newMatch();launchServe();serveFault('NET');assert.equal(state,'fault');assert.equal(score[0],0);for(let i=0;i<220;i++)tick(1/120);assert.equal(state,'serve');assert.equal(serveAttempt,2);launchServe();serveFault('NET');assert.equal(score[0],1);assert.equal(stats.points,1);serveFault('NET');assert.equal(score[0],1);for(let i=0;i<300;i++)tick(1/120);assert.equal(state,'point');continuePoint();assert.equal(state,'serve');assert.equal(serveAttempt,1);assert.equal(receiveLane,0);`);
run('service rotation and tiebreak order',`newMatch();score=[3,0];state='play';point(0,'WINNER');setupServe();assert.equal(serverIndex,1);tiebreak=true;tbStart=1;score=[0,0];assert.equal(serverForPoint(),2);score=[1,0];assert.equal(serverForPoint(),1);score=[1,1];assert.equal(serverForPoint(),1);score=[2,1];assert.equal(serverForPoint(),3);`);
run('let preserves attempt and score',`newMatch();setupServe(2);launchServe();serveLet();assert.equal(state,'let');for(let i=0;i<185;i++)tick(1/120);assert.equal(state,'serve');assert.equal(serveAttempt,2);assert.equal(score[0]+score[1],0);`);
run('serve box and fence faults',`newMatch();launchServe();Object.assign(ball,{x:100,y:360,z:.1,vz:-100,vx:0,vy:0,last:1,bounces:0});physics(ball,.01);assert.equal(state,'fault');newMatch();launchServe();Object.assign(ball,{x:300,y:3,z:30,vz:0,vx:0,vy:-200,last:1,bounces:1,legalBounce:true});physics(ball,.02);assert.equal(state,'fault');`);
run('return must bounce and correct receiver',`newMatch();launchServe();ball.x=players[0].x+50;ball.y=players[0].y;ball.z=25;hit(players[0],false,.4,{x:0,y:0});assert.equal(score[1],1);`);
run('AI levels and increasing power risk apply to everyone',`newMatch();for(const p of players){assert(errorChance(p,.95)>errorChance(p,.35));}rivalLevel='beginner';const easy=errorChance(players[2],.6);rivalLevel='advanced';assert(errorChance(players[2],.6)<easy);assert(LEVELS.advanced.reaction<LEVELS.beginner.reaction);assert(LEVELS.advanced.speed>LEVELS.beginner.speed);rivalLevel='club';`);
run('AI placement adapts to unoccupied lanes instead of fixed receiver quotas',`newMatch();const p=players[2];let lower=0,upper=0;players[0].y=players[1].y=80;for(let i=0;i<100;i++)lower+=aiPlacement(p,false).targetY>300;players[0].y=players[1].y=420;for(let i=0;i<100;i++)upper+=aiPlacement(p,false).targetY<200;assert(lower>65);assert(upper>65);`);
run('net, glass, fence misses travel physically and lose the point',`for(let kind=0;kind<3;kind++){newMatch();state='play';ball={x:300,y:250,z:40,vx:0,vy:0,vz:0,last:0,bounces:0,legalBounce:false};const original=Math.random;Math.random=()=>[.05,.5,.9][kind];const shot=mishit(players[0],shotPlan(players[0],false,.6,{x:0,y:0}),.6);Math.random=original;Object.assign(ball,shot);for(let i=0;i<600&&state==='play';i++)physics(ball,1/120);assert.equal(score[1],1,'kind '+kind+' '+notice);assert(notice.includes(['NET','GLASS','FENCE'][kind]),notice);}`);
run('high hard contact creates smash; low contact does not',`newMatch();state='play';const orig=Math.random;Math.random=()=>.999;players[0].x=370;players[0].y=250;ball={x:420,y:250,z:120,vx:0,vy:0,vz:-40,last:1,bounces:0};assert(hit(players[0],false,.9,{x:1,y:0}));assert(ball.smash);assert(ball.vz<0);assert.equal(stats.smashes,1);Math.random=orig;`);
run('smash bounces then clears the four metre back enclosure',`newMatch();state='play';ball={x:420,y:250,z:150,last:0,bounces:0,legalBounce:false,smash:true};Object.assign(ball,smashPlan(players[0],.92,{x:1,y:0}));for(let i=0;i<500&&state==='play';i++)physics(ball,1/120);assert.equal(score[0],1);assert(notice.includes('POR CUATRO'),notice);assert.equal(stats.exits,1);`);
run('por tres legal side exit; direct exit is a fault',`newMatch();state='play';ball={x:740,y:4,z:175,vx:0,vy:-250,vz:50,last:0,bounces:1,legalBounce:true};physics(ball,.02);assert.equal(score[0],1);assert(notice.includes('POR TRES'));newMatch();state='play';ball={x:740,y:4,z:175,vx:0,vy:-250,vz:50,last:0,bounces:0,legalBounce:false};physics(ball,.02);assert.equal(score[1],1);assert(notice.includes('OUT BEFORE BOUNCE'));`);
run('low legal fence bounce stays live',`newMatch();state='play';ball={x:700,y:4,z:40,vx:0,vy:-200,vz:50,last:0,bounces:1,legalBounce:true};physics(ball,.02);assert.equal(state,'play');assert(ball.vy>0);`);
run('charge, short shot and eight directions retained',`newMatch();state='play';beginCharge('Mouse1',false);charge.power=.5;keys.KeyA=true;updateSwipe(charge.origin.x-80,charge.origin.y);releaseCharge('Mouse1');assert(Number.isFinite(pendingShot.aim.x));keys.KeyA=false;ball={x:300,y:250,z:30};const choices=new Set();for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)if(x||y){const c=shotPlan(players[0],false,.6,{x,y});choices.add(c.targetX+','+c.targetY);}assert.equal(choices.size,8);cancelShot();`);
run('five-minute match simulation ends points, preserves lanes, remains finite',`newMatch();for(let i=0;i<36000&&state!=='over';i++){if(state==='point')continuePoint();tick(1/120);assert(Number.isFinite(ball.x)&&Number.isFinite(ball.z));if(state==='play'){for(const p of players)if(!p.human&&!p.returningServe){assert(p.lane===0?p.y<=232:p.y>=268);assert(courtSide(p.team)===0?p.x<=480:p.x>=520);}}}assert(stats.points>=8);assert(best>=2);console.log('Last points',pointLog.slice(-6));console.log('Simulation:',stats.points,'points;',stats.smashes,'smashes;',stats.errors,'errors; games',games,'sets',sets);`);

run('angled smash rebounds from glass then exits por tres',`newMatch();state='play';ball={x:420,y:250,z:150,last:0,bounces:0,legalBounce:false,smash:true};Object.assign(ball,smashPlan(players[0],.92,{x:1,y:-1}));let backRebound=false;for(let i=0;i<500&&state==='play';i++){physics(ball,1/120);if(ball.vx<0)backRebound=true;}assert(backRebound);assert.equal(score[0],1);assert(notice.includes('POR TRES'),notice);`);

run('point countdown preserves score while ball coasts then starts one serve',`newMatch();state='play';point(0,'NET');const saved=JSON.stringify({score,games,sets});for(let i=0;i<360;i++)tick(1/120);assert.equal(state,'point');assert.equal(JSON.stringify({score,games,sets}),saved);assert.equal($('#point-winner').textContent,'YOU + CESAR · SCORED');assert.equal($('#point-reason').textContent,'INTO THE NET');assert.equal($('#point-score')['aria-label'],'15 – 0');assert($('#point-score').innerHTML.includes('score-old'));assert($('#point-score').innerHTML.includes('score-new'));for(let i=0;i<122;i++)tick(1/120);assert.equal(state,'serve');const timer=serveTimer;continuePoint();assert.equal(serveTimer,timer);`);
run('ordinary smash stays inside and elite conditions are required for extra bounce',`newMatch();state='play';ball={x:420,y:250,z:120,last:0,bounces:0,legalBounce:false,smash:true};Object.assign(ball,smashPlan(players[0],.8,{x:1,y:0}));assert.equal(ball.smashBounce,.62);for(let i=0;i<500&&state==='play';i++)physics(ball,1/120);assert.equal(stats.exits,0);ball={x:300,y:250,z:150};assert.equal(smashPlan(players[0],.95,{x:1,y:0}).smashBounce,.62);ball={x:420,y:250,z:150};assert.equal(smashPlan(players[0],.95,{x:1,y:0}).smashBounce,.91);`);
run('club rally error rate is lower while power still adds risk',`newMatch();assert(errorChance(players[2],.6)<.05);assert(errorChance(players[0],.6)<.03);assert(errorChance(players[2],.95)>errorChance(players[2],.6));`);

run('body proximity cannot hit; racket face and arc can hit',`newMatch();state='play';const p=players[0];p.x=250;p.y=330;p.angle=0;ball={x:250,y:330,z:30,last:1,bounces:1};assert.equal(hit(p,false,.5,{x:0,y:0}),false);assert.equal(racketContact(p,ball),null);ball.x=270;assert.equal(racketContact(p,ball),null);ball.x=300;assert(racketContact(p,ball));const saved=Math.random;Math.random=()=>.999;assert(hit(p,false,.5,{x:0,y:0}));Math.random=saved;const pose=displayRacketPose(p);assert(Math.hypot(pose.x-ball.x,pose.y-ball.y)<20);assert.equal(pose.z,ball.z);assert.equal(hits,1);`);
run('ball behind player is not reached by forehand',`const p=players[0];p.x=250;p.y=250;p.angle=0;assert.equal(racketContact(p,{x:200,y:250,z:30}),null);p.angle=Math.PI;assert(racketContact(p,{x:200,y:250,z:30}));`);

run('forward ready pose, loaded backswing, and rising lob follow-through',`newMatch();const p=players[0];p.angle=0;let pose=displayRacketPose(p);assert(Math.abs(pose.y-p.y)<6);assert(pose.x-p.x>39);beginCharge('Mouse2',true);charge.power=1;pose=displayRacketPose(p);assert(pose.x<p.x);assert(pose.z<0);cancelShot();p.swing=.11;p.lobSwing=true;p.contactZ=30;p.impactAngle=.5;assert(displayRacketPose(p).z>90);`);
run('winner celebrations have side-confined confetti, scale for match and reset',`newMatch();celebrate(0,'POINT','NET');assert.equal(celebration.particles.length,54);assert(celebrationPose(players[0]));assert.equal(celebrationPose(players[2]),null);assert.equal(celebration.half,0);assert(celebration.particles.every(p=>p.x>0&&p.x<500));const short=celebration.duration;celebrate(0,'GAME','DOUBLE BOUNCE');assert(celebration.duration>short);celebrate(1,'MATCH','DOUBLE BOUNCE');assert.equal(celebration.particles.length,360);assert(celebration.particles.every(p=>p.x>500&&p.x<1000));endsChanged=true;celebrate(0,'POINT','NET');assert.equal(celebration.half,1);assert(celebration.particles.every(p=>p.x>500));celebration.age=celebration.duration;assert.equal(celebrationPose(players[0]),null);continuePoint();setupServe();assert.equal(celebration,null);`);

run('cursor gives an unrestricted unit direction and release locks it',`newMatch();state='play';scale=1;ox=oy=0;const p=players[0];mouse={x:p.x-80,y:p.y};p.angle=Math.PI;beginCharge('PadA',false);assert.equal(aimInput().x,-1);assert(Math.abs(aimInput().y)<1e-8);assert.equal(aimInput().targetX,undefined);charge.power=.5;updateSwipe(p.x,p.y+100);p.angle=Math.PI/2;releaseCharge('PadA');assert.equal(pendingShot.aim.y,1);updateSwipe(p.x+100,p.y);assert.equal(pendingShot.aim.y,1);assert.equal(cursorAim().x,1);`);
run('360 degree aim preserves heading for drives, lobs and smashes',`newMatch();ball={x:300,y:250,z:30};const p=players[0];for(let i=0;i<32;i++){const angle=i*Math.PI/16,aim={x:Math.cos(angle),y:Math.sin(angle),mouse:true};for(const lob of [false,true]){const shot=shotPlan(p,lob,.6,aim);assert(Math.abs(Math.atan2(shot.vy,shot.vx)-Math.atan2(aim.y,aim.x))<1e-8);}const smash=smashPlan(p,.8,aim);assert(Math.abs(Math.atan2(smash.vy,smash.vx)-Math.atan2(aim.y,aim.x))<1e-8);}const back=shotPlan(p,false,.7,{x:-1,y:0,mouse:true});assert(back.targetX<0);assert(back.vx<0);`);
run('own glass rebound crosses net and lands legally; own fence and floor lose',`newMatch();state='play';ball={x:80,y:140,z:30,last:0,bounces:0,legalBounce:false};Object.assign(ball,shotPlan(players[0],false,.8,{x:-1,y:0,mouse:true}));let rebound=false;for(let i=0;i<300&&state==='play'&&!ball.legalBounce;i++){physics(ball,1/240);if(ball.vx>0)rebound=true;}assert(rebound);assert(ball.legalBounce);assert(ball.x>500);assert.equal(state,'play');newMatch();state='play';ball={x:300,y:4,z:30,vx:0,vy:-200,vz:0,last:0,bounces:0,legalBounce:false};physics(ball,.02);assert.equal(score[1],1);assert(notice.includes('OWN FENCE'));newMatch();state='play';ball={x:300,y:250,z:.1,vx:0,vy:0,vz:-100,last:0,bounces:0};physics(ball,.02);assert.equal(score[1],1);`);

run('power widens actual landing spread within shown radius',`newMatch();ball={x:300,y:250,z:30};assert(dispersionRadius(.9)>dispersionRadius(.4)*3);const base=shotPlan(players[0],false,.6,{x:1,y:0,mouse:true});let far=0;for(let i=0;i<300;i++){const s=disperseShot(base,.9);const d=Math.hypot(s.targetX-base.targetX,s.targetY-base.targetY);assert(d<=dispersionRadius(.9)+1e-7);far=Math.max(far,d);}assert(far>dispersionRadius(.9)*.9);const saved=JSON.stringify(ball);landingPreview(players[0],true,.6,{x:1,y:0,mouse:true});assert.equal(JSON.stringify(ball),saved);`);
run('traida awards hitter once and waits for continue, both sides',`for(const team of [0,1]){newMatch();state='play';ball={x:team?499:501,y:250,z:80,vx:team?300:-300,vy:0,vz:20,last:team,bounces:1,legalBounce:true,serve:false};assert.equal(physics(ball,.02),'TRAÍDA');assert(ball.returned);assert.equal(state,'point');for(let i=0;i<300&&state==='play';i++)physics(ball,1/120);assert.equal(score[team],1);assert.equal(stats.exits,0);assert.equal(state,'point');assert($('#point-reason').textContent.includes('TRAÍDA'));point(team,'TRAÍDA');assert.equal(score[team],1);continuePoint();assert.equal(state,'serve');}`);
run('traida requires legal bounce and net clearance',`newMatch();state='play';let b={x:501,y:250,z:10,vx:-300,vy:0,vz:0,last:0,bounces:1,legalBounce:true};assert.equal(physics(b,.02,false),'NET');b={x:501,y:250,z:80,vx:-300,vy:0,vz:0,last:0,bounces:0,legalBounce:false};assert.equal(physics(b,.02,false),null);assert.equal(score[0],0);`);

run('controller full charge takes 0.6 seconds',`newMatch();beginCharge('PadA',false);tick(.3);assert(Math.abs(charge.power-.5)<1e-8);tick(.3);assert.equal(charge.power,1);cancelShot();`);

run('Spanish translates dynamic match results and switching preserves game state',`newMatch();state='play';hits=7;point(0,'DOUBLE BOUNCE');const saved=JSON.stringify({score,games,sets,ball,state,hits});setLanguage('es');assert.equal($('#point-winner').textContent,'TÚ + CESAR · PUNTO');assert.equal($('#point-reason').textContent,'DOBLE BOTE');assert.equal($('#point-kind').textContent,'PUNTO GANADO');assert.equal($('#point-detail').textContent,'');assert.equal($('#point-countdown').textContent,'PRÓXIMO SAQUE · 4');assert.equal(tr('ALBERT SERVING · 1ST · DIAGONAL BOTTOM'),'ALBERT AL SAQUE · 1.º · DIAGONAL ABAJO');assert.equal(tr('LOB 80%'),'GLOBO 80%');assert.equal(tr('3 m · FENCE'),'3 m · MALLA');assert.equal(tr('DOUBLE FAULT · WRONG SERVICE BOX'),'DOBLE FALTA · CUADRO DE SAQUE INCORRECTO');assert.equal(JSON.stringify({score,games,sets,ball,state,hits}),saved);setLanguage('en');assert.equal($('#point-winner').textContent,'YOU + CESAR · SCORED');assert.equal($('#point-reason').textContent,'DOUBLE BOUNCE');assert.equal($('#point-countdown').textContent,'NEXT SERVE · 4');`);

run('match menu restores every phase without advancing score or serve',`newMatch();for(const phase of ['intro','serve','play','fault','let','point','over']){state=phase;keys.KeyW=true;const saved=JSON.stringify({score,games,sets,ball,serveTimer});togglePause();assert.equal(state,'paused');assert.equal(keys.KeyW,false);for(let i=0;i<120;i++)tick(1/120);togglePause();assert.equal(state,phase);assert.equal(JSON.stringify({score,games,sets,ball,serveTimer}),saved);}`);

