const baseEl=box.document.querySelector;box.document.querySelector=s=>{const e=baseEl(s);e.addEventListener=noop;return e;};
box.document.querySelectorAll=s=>s==='.result-teams span'?[el('team0'),el('team1')]:[];
box.performance={now:()=>1000};box.setInterval=noop;box.setTimeout=noop;box.URL=URL;box.location={href:'https://padel.test/',origin:'https://padel.test'};box.sessionStorage={getItem:()=>null};
vm.runInContext(fs.readFileSync('web/multiplayer.js','utf8'),box);
run('four humans have independent controls, charge, and legal team bounds',`network.active=true;network.isHost=true;network.slot=0;network.session={id:'host'};network.room={host:'host',members:[0,1,2,3].map(i=>({id:i?'g'+i:'host',slot:i,name:'PLAYER '+i,online:true}))};newMatch();state='play';ball.z=1000;assert(players.every(p=>p.human));const original=players.map(p=>({x:p.x,y:p.y}));network.acceptInput('g2',{seq:1,x:-1,y:1,events:[{id:1,kind:'charge',lob:true,aim:{targetX:200,targetY:100}}]});for(let i=0;i<60;i++)tick(1/120);assert(players[2].x<original[2].x);assert(players[2].y>original[2].y);assert.equal(players[0].x,original[0].x);assert(Math.abs(players[2].netCharge.power-.5/.6)<1e-7);assert.equal(charge,null);network.acceptInput('g2',{seq:2,x:0,y:0,events:[{id:2,kind:'release',aim:{targetX:200,targetY:100}}]});const pending=players[2].netPending;assert(pending.lob);assert(Math.abs(pending.power-.5/.6)<1e-7);network.acceptInput('g2',{seq:3,x:0,y:0,events:[{id:2,kind:'release'}]});assert.equal(players[2].netPending,pending);network.slot=3;keys.KeyA=true;const x=players[3].x;tick(.05);assert(players[3].x<x);assert(players[3].x>=520);keys.KeyA=false;`);
run('missing guest falls back to AI and stale inputs stop',`network.slot=0;network.received.g2.time=-10000;network.beforeTick(.01);assert.equal(players[2].netInput.x,0);assert.equal(players[2].netPending,null);network.room.members[2].online=false;network.applyRoster();assert.equal(players[2].human,false);network.room.members[2].online=true;network.applyRoster();assert.equal(players[2].human,true);`);
run('guest consumes monotonic shared score and cannot advance point',`network.isHost=true;state='play';point(0,'DOUBLE BOUNCE');pointRemaining=2.5;const snapshot=network.snapshot();assert.equal(snapshot.pointRemaining,2.5);network.isHost=false;network.slot=2;network.session={id:'g2'};network.started=true;network.receiveSnapshot(snapshot);assert.equal(state,'point');assert.equal($('#continue-point').textContent,'WAITING FOR HOST');assert.equal(pointRemaining,2.5);const saved=JSON.stringify(score);continuePoint();assert.equal(state,'point');assert.equal(JSON.stringify(score),saved);network.receiveSnapshot({...snapshot,seq:snapshot.seq-1,score:[0,0]});assert.equal(JSON.stringify(score),saved);network.receiveSnapshot({...snapshot,seq:snapshot.seq+1,state:'paused'});network.receiveSnapshot({...snapshot,seq:snapshot.seq+2});assert.equal(state,'point');assert.equal($('#continue-point').textContent,'WAITING FOR HOST');network.active=false;`);
run('guest moves immediately without a new network packet and remains in bounds',`network.active=true;network.isHost=false;network.slot=2;network.session={id:'g2'};network.predicted=null;network.rtt=180;state='play';players[2].x=770;players[2].y=140;players[2].vx=0;players[2].vy=0;network.lastSnapshot={...network.snapshot(),state:'play'};network.previous=null;network.lastReceived=performance.now();const x=players[2].x;keys.KeyA=true;network.renderGuest(1/60);assert(players[2].x<x);for(let i=0;i<30;i++)network.renderGuest(1/60);assert(players[2].x>=520);keys.KeyA=false;state='point';network.renderGuest(1/60);assert.equal(network.predicted,null);network.active=false;`);
run('serving partner starts at the net on either end and on repeat serves',`
 network.active=false;newMatch();
 for(const far of [false,true])for(const attempt of [1,2])for(let turn=0;turn<4;turn++)for(let parity=0;parity<2;parity++){
  endsChanged=far;gameTurn=turn;score=[parity,0];setupServe(attempt);
  const server=players[serverIndex],partner=players.find(p=>p.team===server.team&&p!==server);
  assert.equal(partner.x,courtSide(server.team)?625:375);
  assert.equal(partner.y,partner.lane?355:145);
  assert.equal(server.x,courtSide(server.team)?900:100);
  assert(teamAtNet[server.team]);assert(!teamAtNet[1-server.team]);
 }
 endsChanged=false;
`);
run('both receivers start behind the service line for every server and score parity',`network.active=false;for(let turn=0;turn<4;turn++)for(let parity=0;parity<2;parity++){gameTurn=turn;tiebreak=false;score=[parity,0];setupServe();const server=players[serverIndex];for(const p of players)if(p.team!==server.team){assert(p.team?p.x>850:p.x<150);assert.equal(p.y,p.lane?355:145);}}`);
run('legal glass touches tracked separately from fence and cleared by a new shot',`newMatch();state='play';const b={x:992,y:140,z:45,vx:200,vy:0,vz:20,last:0,bounces:1,legalBounce:true};physics(b,.025,false);assert.equal(b.glassTouches,1);const fence={x:700,y:3,z:45,vx:0,vy:-200,vz:20,last:0,bounces:1,legalBounce:true};physics(fence,.025,false);assert.equal(fence.glassTouches,undefined);launchServe();assert.equal(ball.glassTouches,0);`);
run('AI chooses reachable back-glass return and refuses an early contact',`newMatch();state='play';const p=players[2];Object.assign(p,{x:900,y:140,angle:0,cool:0,readyAt:0,planShot:shotSerial,planUntil:0,wallPreference:true});ball={x:945,y:140,z:50,vx:240,vy:0,vz:90,last:0,bounces:1,legalBounce:true,glassTouches:0};const plan=receivePlan(p);assert(plan?.waitGlass);assert.equal(hit(p,false,.5,{x:-1,y:0}),false);for(let i=0;i<30;i++)physics(ball,.01,false);assert(ball.glassTouches>0);`);
run('AI abandons glass waiting when the next bounce ends the point first',`newMatch();const p=players[2];Object.assign(p,{x:740,y:140,planShot:shotSerial,planUntil:0,wallPreference:true});ball={x:770,y:140,z:14,vx:35,vy:0,vz:-60,last:0,bounces:1,legalBounce:true,glassTouches:0};const plan=receivePlan(p);assert(!plan?.waitGlass);`);
run('AI rally simulation includes real post-glass returns and direct shots',`const savedReset=resetPlayers,savedHit=hit;let wallReturns=0,directReturns=0;resetPlayers=function(){savedReset();for(const p of players)p.human=false;};hit=function(...args){const glass=ball.glassTouches||0;const yes=savedHit(...args);if(yes){if(glass)wallReturns++;else directReturns++;}return yes;};try{newMatch();for(let i=0;i<36000;i++){if(state==='point'||state==='over')continuePoint();tick(1/120);}console.log('AI wall-play sample:',wallReturns,'glass returns;',directReturns,'direct returns; best rally',best);assert(wallReturns>=8);assert(directReturns>=8);}finally{resetPlayers=savedReset;hit=savedHit;}`);
run('side-glass return is planned in the glass section, not treated as a fence',`network.active=false;newMatch();state='play';const p=players[2];Object.assign(p,{x:890,y:80,planShot:shotSerial,planUntil:0,wallPreference:true});ball={x:900,y:25,z:45,vx:-30,vy:-160,vz:65,last:0,bounces:1,legalBounce:true,glassTouches:0};assert(receivePlan(p)?.waitGlass);for(let i=0;i<15;i++)physics(ball,.01,false);assert.equal(ball.glassTouches,1);assert(ball.vy>0);`);


run('four shot tiers, higher lobs, and red lob landing risk',`newMatch();assert.equal(new Set([.2,.5,.75,.95].map(shotColor)).size,4);const origin={x:300,y:250,z:30};const aim={targetX:750,targetY:250};assert(shotPlan(players[0],true,.5,aim,origin).vz>=450);let outside=0;for(let i=0;i<1000;i++){const shot=disperseShot(shotPlan(players[0],true,.9,aim,origin),.9,origin,true);if(shot.targetX<500||shot.targetX>1000||shot.targetY<0||shot.targetY>500)outside++;}assert(outside>900);console.log('Red lob out-of-target-court sample:',outside+'/1000');assert(dispersionRadius(.75)>dispersionRadius(.25)*5);`);
run('countdown stops on pause and match end stays manual',`newMatch();state='play';point(0,'NET');togglePause();const left=pointRemaining;tick(2);assert.equal(pointRemaining,left);togglePause();assert.equal(state,'point');tick(left+.01);assert.equal(state,'serve');state='over';showPointResult(0,'DOUBLE BOUNCE','MATCH');tick(10);assert.equal(state,'over');`);

run('yellow near a line misses more than blue and blue flies slower',`newMatch();const origin={x:300,y:250,z:30},aim={targetX:930,targetY:65};let blue=0,yellow=0;for(let i=0;i<1000;i++){for(const q of [.2,.75]){const shot=disperseShot(shotPlan(players[0],false,q,aim,origin),q,origin);if(shot.targetX>1000||shot.targetX<500||shot.targetY<0||shot.targetY>500){if(q===.2)blue++;else yellow++;}}}assert.equal(blue,0);assert(yellow>150);const a=shotPlan(players[0],false,.2,aim,origin),b=shotPlan(players[0],false,.75,aim,origin);assert(Math.hypot(a.vx,a.vy)<Math.hypot(b.vx,b.vy));console.log('Near-line landing misses: blue',blue,'yellow',yellow);`);
run('bounce marker predicts lob and next bounce after glass without changing play',`newMatch();const samples=[{x:300,y:200,z:35,...trajectory(300,200,35,760,180,460),last:0,bounces:0,legalBounce:false,crossed:false,serve:false},{x:950,y:350,z:70,vx:230,vy:20,vz:80,last:0,bounces:1,legalBounce:true,crossed:true,serve:false}];for(const source of samples){const saved=JSON.stringify(source),scoreBefore=JSON.stringify(score),target=nextFloorBounce(source);assert(target);const b={...source};let glass=false;for(let i=0;i<480;i++){physics(b,1/120,false);if(b.glassTouches)glass=true;if(b.bounces>source.bounces)break;}assert(Math.abs(target.x-b.x)<.001);assert(Math.abs(target.y-b.y)<.001);if(source.bounces)assert(glass);assert.equal(JSON.stringify(source),saved);assert.equal(JSON.stringify(score),scoreBefore);}assert.equal(nextFloorBounce({x:490,y:250,z:5,vx:400,vy:0,vz:0,last:0,bounces:0}),null);assert.equal(nextFloorBounce({x:990,y:250,z:250,vx:400,vy:0,vz:0,last:0,bounces:1,legalBounce:true}),null);`);
run('camera shake is bounded, short, and cosmetic',`newMatch();state='play';const saved=JSON.stringify({ball,players,score});impactShake({power:.5});assert(shakeTime>0);impactShake({power:.9});assert(shakeTime>0);const red=shakeStrength;impactShake({power:.7,smash:true});assert(shakeStrength>red);for(let i=0;i<60;i++){updateCamera(1/120);assert(Math.abs(shakeX)<=8);assert(Math.abs(shakeY)<=8);}assert.equal(shakeTime,0);assert.equal(shakeX,0);assert.equal(shakeY,0);assert.equal(JSON.stringify({ball,players,score}),saved);`);
run('speed defaults to 100, preserves blue green, and 150 restores all shot pace',`gameSpeed=100;assert.equal(ballPace({power:.2}),1);assert.equal(ballPace({power:.5}),1);assert(Math.abs(ballPace({power:.95})-2/3)<1e-8);gameSpeed=150;for(const power of [.2,.5,.75,.95])assert.equal(ballPace({power}),1);gameSpeed=100;`);
run('directional counter-wall drive reaches opponent floor',`newMatch();const p=players[0],origin={x:150,y:350,z:35},shot=shotPlan(p,false,.5,{x:-1,y:0,mouse:true},origin);const b={...origin,...shot,last:0,bounces:0,legalBounce:false,serve:false,power:.5};let reflected=false,result=null;for(let i=0;i<500;i++){result=physics(b,1/120,false);if(b.vx>0)reflected=true;if(result||b.bounces>0)break;}assert(reflected);assert.equal(result,null);assert(b.x>500);assert.equal(b.bounces,1);`);
run('direction vectors survive guest input and speed is in host snapshot',`network.active=true;network.isHost=true;network.slot=0;network.session={id:'host'};network.room={host:'host',members:[{id:'host',slot:0,online:true},{id:'direction-guest',slot:2,online:true}]};newMatch();state='play';network.acceptInput('direction-guest',{seq:1,x:0,y:0,aim:{x:1,y:0},events:[{id:1,kind:'charge',aim:{x:1,y:0}}]});assert.equal(players[2].netCharge.aim.x,1);assert.equal(players[2].netCharge.aim.targetX,undefined);gameSpeed=125;assert.equal(network.snapshot().gameSpeed,125);gameSpeed=100;network.active=false;`);
run('lob exceeds maximum reach and color threshold matches hit ceiling',`newMatch();const p=players[0],origin={x:250,y:350,z:30},shot=shotPlan(p,true,.5,{x:1,y:0,mouse:true},origin);assert(shot.vz>=550);assert(origin.z+shot.vz**2/(2*G)>350);assert(!ballOutOfReach({z:205}));assert(ballOutOfReach({z:206}));state='play';p.angle=0;p.cool=0;ball={x:p.x+40,y:p.y,z:206,vx:0,vy:0,vz:-80,last:1,bounces:0};assert.equal(hit(p,false,1,{x:1,y:0,mouse:true}),false);`);
run('human serve has 10 seconds and launches once from the rendered racket face',`network.active=false;newMatch();gameTurn=0;setupServe();assert.equal(serverIndex,0);assert.equal(serveTimer,10);const p=players[0];assert.equal(queueServe(players[1],.5,{x:1,y:0}),false);const aim={x:.95,y:-.3,mouse:true};assert(queueServe(p,.45,aim));assert(!queueServe(p,.8,aim));tick(.22);assert.equal(state,'serve');assert(ball.z<2);tick(.24);assert.equal(state,'play');assert(ball.serve);assert.equal(ball.power,.45);const face=displayRacketPose(p);assert(Math.abs(ball.x-face.x)<1e-8);assert(Math.abs(ball.y-face.y)<1e-8);assert(Math.hypot(ball.x-p.x,ball.y-p.y)>39);assert.equal(p.servePending,null);const projected={...ball};let result=null;for(let i=0;i<480;i++){result=physics(projected,1/120,false);if(result||projected.bounces)break;}assert.equal(result,null);assert.equal(projected.bounces,1);setupServe();tick(10.1);assert.equal(state,'play');`);
run('guest server release submits aim and power to host serve flow',`network.active=true;network.isHost=true;network.slot=0;network.session={id:'host'};network.room={host:'host',members:[{id:'host',slot:0,online:true},{id:'serve-guest',slot:2,online:true}]};newMatch();assert.equal(serverIndex,2);assert.equal(serveTimer,10);network.acceptInput('serve-guest',{seq:1,aim:{x:-.9,y:.3},events:[{id:1,kind:'charge',aim:{x:-.9,y:.3}}]});tick(.6);network.acceptInput('serve-guest',{seq:2,aim:{x:-.9,y:.3},events:[{id:2,kind:'release',aim:{x:-.9,y:.3}}]});assert(players[2].servePending);assert.equal(players[2].servePending.power,1);tick(.46);assert.equal(state,'play');assert(ball.vx<0);assert(ball.serve);network.active=false;`);

run('post-point ball keeps moving without extra points or ending early',`newMatch();state='play';ball={x:780,y:350,z:20,vx:220,vy:15,vz:90,last:0,power:.5};point(0,'DOUBLE BOUNCE');const scoreBefore=JSON.stringify(score),count=stats.points,x=ball.x;for(let i=0;i<120;i++)tick(1/120);assert(ball.x!==x);assert.equal(stats.points,count);assert.equal(JSON.stringify(score),scoreBefore);assert.equal(state,'point');assert(afterPointAge>.9);`);
run('power tiers produce deep, middle, and near-net glass rebounds',`newMatch();const landings=[];for(const power of [.2,.5,.75,.95]){const b={x:994,y:350,z:80,vx:650,vy:0,vz:60,last:0,bounces:1,legalBounce:true,power,smash:power>.85};const target=nextFloorBounce(b);assert(target);landings.push(target.x);}console.log('Back-glass landing X by tier:',landings);assert(landings[0]>810);assert(landings[1]>740);assert(landings[2]>580&&landings[2]<740);assert(landings[3]<570&&landings[3]>500);`);
run('red smash can threaten a traida and can be volleyed before crossing',`newMatch();let b={x:994,y:350,z:100,vx:750,vy:0,vz:100,last:0,bounces:1,legalBounce:true,power:.95,smash:true};let result;for(let i=0;i<400;i++){result=physics(b,1/120,false);if(result)break;}assert.equal(result,'TRAÍDA');state='play';const p=players[3];p.human=true;p.x=550;p.y=350;p.angle=Math.PI;p.cool=0;ball={x:510,y:350,z:60,vx:-500,vy:0,vz:0,last:0,bounces:1,legalBounce:true,power:.95};assert(hit(p,false,.5,{x:-1,y:0,mouse:true}));assert.equal(ball.last,1);`);
run('lobs travel faster while keeping high trajectory',`newMatch();gameSpeed=100;assert.equal(ballPace({shotKind:'LOB',power:.5}),1.35);assert.equal(ballPace({shotKind:'LOB',power:.95}),1.35);assert.equal(ballPace({power:.5}),1);`);
run('AI comfortable shots are safer than pressured returns',`newMatch();const p=players[2];p.vx=p.vy=0;ball={x:p.x-40,y:p.y,z:50,vx:150,vy:0,power:.4};const easy=errorChance(p,.55),easySpread=.22+.55*shotDifficulty(p);p.vx=180;ball.z=10;ball.vx=1000;const hard=errorChance(p,.55),hardSpread=.22+.55*shotDifficulty(p);assert(easy<.02);assert(hard>easy*3);assert(hardSpread>easySpread*2);console.log('AI error chance comfortable / pressured:',easy,hard);`);
run('AI lobs net opponents and chooses attacks against deep defenders',`newMatch();const p=players[2];p.x=875;p.vx=p.vy=0;ball={x:p.x-40,y:p.y,z:50,vx:150,vy:0,power:.4};players[0].x=players[1].x=380;let crowded=0;for(let i=0;i<400;i++){const c=aiChoice(p);crowded+=c.lob;assert(!c.lob||c.power<=.62);}players[0].x=players[1].x=125;p.x=620;ball.x=580;let deep=0,attacks=0;for(let i=0;i<400;i++){const c=aiChoice(p);deep+=c.lob;attacks+=c.attack;}assert(crowded>260);assert(deep<80);assert(attacks>160);console.log('Lob choices vs net / deep:',crowded,deep);`);
run('both AI partners advance after a lob and retreat when lobbed',`newMatch();const p=players[2];p.angle=Math.PI;p.cool=0;p.readyAt=0;p.receivePlan=null;p.choice={targetX:180,targetY:350};state='play';ball={x:p.x-40,y:p.y,z:45,vx:150,vy:0,vz:0,last:0,bounces:1,legalBounce:true};const rng=Math.random;Math.random=()=>.5;try{assert(hit(p,true,.5,{x:-1,y:0,mouse:true}));}finally{Math.random=rng;}assert(teamAtNet[1]);assert(aiRecovery(p).x<660);assert(aiRecovery(players[3]).x<660);ball.last=0;assert.equal(aiRecovery(p).x,875);assert.equal(aiRecovery(players[3]).x,875);assert(aiRecovery(p).y>=55&&aiRecovery(p).y<=210);assert(aiRecovery(players[3]).y>=290&&aiRecovery(players[3]).y<=445);`);
run('resting racket is edge-on and opens through charge and contact',`assert.equal(racketFaceWidth(0,0,0),.18);assert(racketFaceWidth(1,0,0)>.75);assert.equal(racketFaceWidth(0,0,.22),1);assert(racketFaceWidth(0,.99,.001)<.21);`);

run('off-ball support shifts with the ball and follows a partner to the net',`newMatch();state='play';const p=players[3];teamAtNet=[false,false];ball={x:800,y:80,last:1,crossed:false,shotKind:'DRIVE'};players[2].x=875;const a=aiRecovery(p);ball.y=420;const b=aiRecovery(p);assert(b.y>a.y+50);ball.x=180;ball.crossed=true;assert(aiRecovery(p).x<660);ball.last=0;ball.shotKind='LOB';assert(aiRecovery(p).x>=850);ball.shotKind='DRIVE';players[2].x=620;assert(aiRecovery(p).x<660);`);
run('low legal glass rebounds lift once, with no fence or high-ball boost',`newMatch();const b={x:994,y:350,z:25,vx:300,vy:0,vz:-100,last:0,bounces:1,legalBounce:true,power:.3};assert.equal(physics(b,.01,false),null);assert(b.vz>=80);assert(b.wallLifted);const target=nextFloorBounce(b);assert(target&&target.x>800);b.vz=-30;wallLift(b,false,500);assert.equal(b.vz,-30);const fence={z:25,vz:-100,legalBounce:true};wallLift(fence,true,300);assert.equal(fence.vz,-100);const high={z:100,vz:-100,legalBounce:true};wallLift(high,false,300);assert.equal(high.vz,-100);`);
run('combo music layers build with rally and reset for serve',`state='play';hits=0;assert.equal(rallyMusicLevel(),0);hits=5;assert.equal(rallyMusicLevel(),1);hits=10;assert.equal(rallyMusicLevel(),2);hits=15;assert.equal(rallyMusicLevel(),3);hits=50;assert.equal(rallyMusicLevel(),4);state='serve';assert.equal(rallyMusicLevel(),0);`);

run('human wall returns have forgiving racket reach and full playable height',`newMatch();state='play';const p=players[0];p.x=250;p.y=330;p.angle=0;p.cool=0;ball={x:312,y:330,z:160,vx:-150,vy:0,vz:-40,last:1,bounces:1,legalBounce:true,glassTouches:1};assert(racketContact(p,ball));assert.equal(humanShotWindow(),.52);const rng=Math.random;Math.random=()=>.5;try{assert(hit(p,false,.4,{x:1,y:0,mouse:true}));}finally{Math.random=rng;}assert.equal(hits,1);assert(Math.abs(Math.hypot(ball.x-p.x,ball.y-p.y)-40)<.001);assert.equal(ball.glassTouches,0);assert.equal(humanShotWindow(),.42);p.cool=0;Object.assign(ball,{x:312,last:1,z:206,glassTouches:1});assert.equal(hit(p,false,.4,{x:1,y:0}),false);Object.assign(ball,{x:250,z:80});assert.equal(racketContact(p,ball),null);Object.assign(ball,{x:330});assert.equal(racketContact(p,ball),null);p.human=false;ball.x=312;assert.equal(racketContact(p,ball),null);`);

