run('18 balanced players randomize without duplicates and persist across points',`assert.equal(roster.length,18);assert.equal(roster[0].name,'Cesar');for(let i=0;i<100;i++)assert.equal(new Set(shuffledLineup().map(p=>p.id)).size,3);globalThis.rosterLineup=[roster[0],roster[6],roster[12]];resetPlayers();assert.equal(players[1].name,'CESAR');assert.equal(players[2].name,'ABEL');assert(Math.abs(players[1].rosterStats.speed-players[3].rosterStats.speed)<=12);assert.equal(Object.values(characterAttributes(roster[0])).reduce((a,b)=>a+b),Object.values(characterAttributes(roster[12])).reduce((a,b)=>a+b));setupServe();assert.equal(players[2].appearance.id,6);assert.equal(players[3].appearance.shirt,roster[12].shirt);assert(teamLabel(1).includes('ABEL'));`);

run('casual rallies accelerate earlier with the same serve, cap and point reset',`
 const previous=globalThis.matchControlMode;globalThis.matchControlMode='casual';
 newMatch();gameSpeed=70;
 const drive={power:.4,shotKind:'DRIVE'},base=baseBallPace(drive);
 for(const [count,multiplier] of [[0,1],[5,1.38],[10,1.72],[25,2.5],[50,3],[60,3]]){
  hits=count;assert(Math.abs(ballPace(drive)/base-multiplier)<1e-9);
  assert.equal(ballPace({...drive,serve:true}),base);
 }
 setupServe();assert.equal(ballPace(drive),base);globalThis.matchControlMode=previous;
`);
run('rally heat increases every hit linearly to 3x, caps and resets',`newMatch();gameSpeed=100;const b={power:.4,shotKind:'DRIVE',z:40};for(const [count,speed] of [...Array.from({length:51},(_,i)=>[i,1+i*.04]),[51,3],[120,3]]){hits=count;assert(Math.abs(rallyPace()-speed)<.001);assert(Math.abs(ballPace(b)-speed)<.001);}hits=50;assert.equal(hotBallColor(b),'#ff4934');assert.equal(ballPace({...b,serve:true}),1);assert(ballOutOfReach({...b,z:220}));setupServe();assert.equal(hits,0);assert.equal(rallyPace(),1);assert.equal(hotBallColor(b),'#e6ef55');`);
run('easy AI contacts are reliable and pressured shots remain fallible',`newMatch();state='play';const p=players[2];p.x=800;p.y=150;p.vx=p.vy=0;ball={x:760,y:150,z:45,vx:150,vy:0,last:0};assert(errorChance(p,.6)<.004);const easy=errorChance(p,.6);p.vx=190;ball.vx=800;ball.z=10;assert(errorChance(p,.78)>easy*8);p.vx=0;ball={x:400,y:200,z:45,vx:100,vy:0,last:1};for(let i=0;i<150;i++){const shot=comfortableReturn(disperseShot(trajectory(ball.x,ball.y,ball.z,800,150,150),.6,ball,false,.07));const b={...ball,...shot,last:0,bounces:0,power:.6};let result=null;for(let j=0;j<600&&!result&&!b.bounces;j++)result=physics(b,1/240,false);assert.equal(result,null);assert.equal(b.bounces,1);assert(b.x>500&&b.x<995);}`);

run('chosen human position and name persist on either side',`globalThis.humanPosition=2;globalThis.customPlayerName='TECH';resetPlayers();assert.equal(localSlot(),2);assert(players[2].human);assert(!players[0].human);assert.equal(players[2].name,'TECH');setupServe();assert.equal(players[2].name,'TECH');assert.equal(players.filter(p=>p.human).length,1);globalThis.humanPosition=0;globalThis.customPlayerName='';`);

run('entire rear enclosure is four metres and reports x4',`for(const pos of [{x:996,y:250,vx:100,vy:0},{x:150,y:4,vx:0,vy:-100},{x:850,y:496,vx:0,vy:100}]){newMatch();state='play';ball={...pos,z:175,vz:0,last:pos.x<500?1:0,bounces:1,legalBounce:true};assert.equal(physics(ball,.001,false),null);ball={...pos,z:205,vz:0,last:pos.x<500?1:0,bounces:1,legalBounce:true};physics(ball,.001);assert(notice.includes('POR CUATRO'),notice);}`);
run('ordinary lobs stay high in flight but do not bounce into routine exits',`newMatch();for(const q of [.2,.5,.62,.8]){const origin={x:250,y:150,z:40};const shot=trajectory(250,150,40,900,350,430+260*q);const b={...origin,...shot,last:0,bounces:0,shotKind:'LOB',power:q};let peak=0,rebound=0,result=null;for(let i=0;i<1200&&!result;i++){result=physics(b,1/240,false);if(b.bounces)rebound=Math.max(rebound,b.z);else peak=Math.max(peak,b.z);}assert(peak>205);assert(rebound<150);assert.notEqual(result,'EXIT');}`);
run('AI mixes safe depths and lanes, remembers team placements, and resets for a new match',`newMatch();const p=players[2];p.x=610;p.y=140;players[0].x=players[1].x=180;players[0].y=140;players[1].y=360;const depths=new Set(),lanes=new Set();let short=0,deep=0,diagonal=0;for(let i=0;i<240;i++){players[0].x=players[1].x=i%80<40?180:400;const c=aiPlacement(p,false);assert(c.targetX>=65&&c.targetX<500);assert(c.targetY>=65&&c.targetY<=435);depths.add(Math.round((500-c.targetX)/100));lanes.add(Math.floor(c.targetY/100));short+=c.targetX>370;deep+=c.targetX<200;diagonal+=Math.abs(c.targetY-p.y)>170;rememberAIPlacement(p,c,false);}assert(depths.size>=3);assert(lanes.size>=4);assert(short>10&&deep>10&&diagonal>10);assert.equal(aiPlacementHistory[1].length,8);assert.equal(aiPlacementHistory[0].length,0);for(let i=0;i<100;i++){const c=aiPlacement(p,true);assert(c.targetX>=65&&c.targetX<=180);}console.log('Placement sample:',{short,deep,diagonal,depths:depths.size,lanes:lanes.size});newMatch();assert.equal(aiPlacementHistory[1].length,0);`);
run('timing uses incoming travel and release grade stays locked',`newMatch();state='play';const p=players[0];p.angle=0;ball={x:p.x+80,y:p.y,z:40,vx:-200,vy:0,last:1};assert.equal(releaseTiming(p),'EARLY');ball.x=p.x+40;assert.equal(releaseTiming(p),'PERFECT');ball.x=p.x-20;assert.equal(releaseTiming(p),'LATE');ball.x=p.x+80;beginCharge('Mouse1',false);charge.power=1;releaseCharge('Mouse1');ball.x=p.x+40;assert.equal(pendingShot.timing,'EARLY');cancelShot();`);
run('perfect full-red drives and overhead smashes land legally',`newMatch();state='play';const p=players[0];p.x=300;p.y=340;p.angle=0;for(const z of [35,140])for(const dy of [-.7,0,.7]){ball={x:340,y:340,z,vx:-200,vy:0,last:1,bounces:z>=90?0:1,glassTouches:0};p.cool=0;assert(hit(p,false,1,{x:1,y:dy,mouse:true},'PERFECT'));assert.equal(ball.timing,'PERFECT');assert.equal(ball.power,1);assert.equal(ball.smash,z>=90);assert.equal(p.timingFeedback,'PERFECT');const b={...ball};let result=null;for(let i=0;i<700&&!result&&!b.bounces;i++)result=physics(b,1/240,false);assert.equal(result,null);assert.equal(b.bounces,1);assert(b.x>500&&b.x<995&&b.y>5&&b.y<495);}cancelShot();`);
run('red body hits use swept height-aware contact and award exactly one point',`newMatch();state='play';players[0].x=200;players[0].y=340;players[1].x=200;players[1].y=140;const from={x:230,y:340,z:40};const b={x:180,y:340,z:40,vx:-500,vy:0,vz:0,last:1,power:1,crossed:true,bounces:0,shotKind:'SMASH'};for(const shotKind of ['VOLLEY','DRIVE','BANDEJA','LOB'])assert.equal(redBodyContact({...b,smash:true,shotKind},from),null);assert.equal(redBodyContact(b,from),players[0]);assert.equal(redBodyContact({...b,power:.8},from),null);assert.equal(redBodyContact({...b,z:200},{...from,z:200}),null);assert.equal(redBodyContact({...b,serve:true},from),null);assert.equal(redBodyContact({...b,last:0},from),null);ball={...b,x:220};const before=score[1];assert.equal(physics(ball,.1),'BODY HIT');assert.equal(score[1],before+1);assert.equal(state,'point');`);
run('perfect red has more pace than a controlled blue and preserves counter-wall aim',`newMatch();const p=players[0];p.x=300;p.y=340;ball={x:340,y:340,z:40,vx:-200,vy:0,last:1};const aim={targetX:850,targetY:340};const red=controlledPerfectShot(p,false,1,aim),blue=controlledPerfectShot(p,false,.25,aim);assert(Math.hypot(red.vx,red.vy)>Math.hypot(blue.vx,blue.vy)*1.15);assert(controlledPerfectShot(p,false,1,{x:-1,y:0,mouse:true}).vx<0);`);

run('overhead tiers and low blue drop volley are distinct',`for(const [q,z,kind] of [[.2,45,'DROP SHOT'],[.2,140,'SOFT OVERHEAD'],[.5,140,'BANDEJA'],[.75,140,'VÍBORA'],[1,140,'SMASH']]){newMatch();state='play';const p=players[0];p.x=400;p.y=340;p.angle=0;p.cool=0;ball={x:440,y:340,z,vx:-180,vy:0,last:1,bounces:0};assert(hit(p,false,q,{x:1,y:0,mouse:true},'PERFECT'));assert.equal(ball.shotKind,kind);assert.equal(ball.smash,kind==='SMASH');if(q>=.35)assert(ball.paceBoost>1);if(kind==='VÍBORA')assert(ball.sideSpin!==0);}`);

run('legal glass return can be countered across the net without crossing players',`newMatch();state='play';const p=players[2];p.human=true;p.x=525;p.y=140;p.angle=Math.PI;p.cool=0;p.readyAt=0;p.receivePlan=null;ball={x:485,y:140,z:140,vx:-200,vy:0,last:0,bounces:1,legalBounce:true,returned:true,glassTouches:1,smash:true};assert(reachBackOverNet(p));assert(hit(p,false,1,{x:-1,y:0,mouse:true},'PERFECT'));assert.equal(ball.last,1);assert(ball.counter);assert.equal(p.shotFeedback,'DRIVE');assert.equal(state,'play');assert(p.x>500);`);


run('idle aim guide is hidden before touching the canvas context',`cancelShot();drawAimGuide(players[0]);`);

run('human contact assistance catches near racket balls while excluding torso and preserving AI reach',`newMatch();const p=players[0];p.x=250;p.y=330;p.angle=0;const b={x:309,y:330,z:45};assert(racketContact(p,b));p.human=false;assert.equal(racketContact(p,b),null);p.human=true;assert.equal(racketContact(p,{...b,x:265}),null);assert.equal(racketContact(p,{...b,x:170}),null);`);

run('swipe length sets power, speed adds only a small bonus, and drag direction ignores cursor position',`swipeSensitivity=140;newMatch();state='play';scale=1;ox=oy=0;const p=players[0];p.angle=0;mouse={x:100,y:100};beginCharge('Mouse1',false);charge.started=0;charge.samples=[{x:100,y:100,t:0}];updateSwipe(140,100,100);const soft=charge.power;assert(soft>.15&&soft<.5);cancelShot();mouse={x:100,y:100};beginCharge('Mouse1',false);charge.started=0;charge.samples=[{x:100,y:100,t:0}];updateSwipe(140,100,20);assert(charge.power>=soft);assert(charge.power<soft+.07);assert.equal(aimInput().x,1);assert.equal(aimInput().y,0);cancelShot();mouse={x:100,y:100};beginCharge('Mouse2',true);const held=charge.power;advanceCharge(2);assert.equal(charge.power,held);charge.samples=[{x:100,y:100,t:0}];updateSwipe(100,20,60);assert.equal(aimInput().y,-1);releaseCharge('Mouse2');assert(pendingShot.lob);assert.equal(pendingShot.aim.y,-1);cancelShot();`);

run('a flick after a long hold still has power and guest release uses bounded gesture power',`newMatch();state='play';scale=1;mouse={x:0,y:0};beginCharge('Mouse1',false);charge.samples=[{x:0,y:0,t:0}];updateSwipe(40,0,2000);assert(charge.power>.15&&charge.power<.5);cancelShot();network.active=true;network.isHost=true;network.slot=0;network.session={id:'host'};network.room={host:'host',members:[{id:'host',slot:0,name:'HOST',online:true},{id:'swipeguest',slot:2,name:'GUEST',online:true}]};newMatch();state='play';network.acceptInput('swipeguest',{seq:1,aim:{x:-1,y:0},events:[{id:1,kind:'charge',gesture:true,aim:{x:-1,y:0}}]});network.acceptInput('swipeguest',{seq:2,aim:{x:-1,y:0},events:[{id:2,kind:'release',gesture:true,power:.73,aim:{x:-1,y:0}}]});assert.equal(players[2].netPending.power,.73);assert.equal(players[2].netPending.aim.x,-1);network.active=false;cancelShot();`);

run('torso tracks the ball while drag aim stays independent and swing pose stays locked',`newMatch();state='play';scale=1;ox=oy=0;const p=players[0];p.angle=0;p.swing=0;p.servePending=null;ball={x:p.x,y:p.y+100,z:40,last:1};mouse={x:p.x+100,y:p.y};beginCharge('Mouse1',false);charge.samples=[{x:mouse.x,y:mouse.y,t:0}];updateSwipe(mouse.x+80,mouse.y,80);for(let i=0;i<100;i++)faceBall(p,1/120);assert(Math.abs(p.angle-Math.PI/2)<.001);assert.equal(aimInput().x,1);releaseCharge('Mouse1');assert.equal(pendingShot.aim.x,1);p.swing=.2;const held=p.angle;ball.x=p.x-100;faceBall(p,1/120);assert.equal(p.angle,held);cancelShot();`);
run('lower swipe sensitivity makes the same flick softer without changing direction',`newMatch();state='play';scale=1;const powers=[];for(const setting of [5,80,140,200]){swipeSensitivity=setting;mouse={x:100,y:100};beginCharge('Mouse1',false);charge.samples=[{x:100,y:100,t:0}];updateSwipe(140,100,20);powers.push(charge.power);assert.equal(aimInput().x,1);cancelShot();}assert(powers[0]<powers[1]&&powers[1]<powers[2]);assert(powers[1]<.65);assert(powers[2]<powers[3]);assert(powers[3]<.85);$('#swipe-sensitivity').oninput({target:{value:'40'}});assert.equal(swipeSensitivity,40);assert.equal($('#sensitivity-value').textContent,'40%');`);

run('new sensitivity scale preserves requested anchors and offers gentler low values',`assert.equal(swipeGain(80),.4);assert.equal(swipeGain(100),.6);assert.equal(swipeGain(5),.025);assert(swipeGain(5)<swipeGain(20));showAimDot=false;drawMouseDot(players[0]);showAimDot=true;`);

run('serve stance faces the opposing court until launch, then human torso tracks ball',`newMatch();state='serve';const p=players[0];p.angle=0;ball.x=p.x-30;ball.y=p.y;faceBall(p,.1);assert.equal(p.angle,0);tick(.01);assert.equal(p.angle,0);state='play';ball.x=p.x-30;ball.y=p.y;p.swing=0;faceBall(p,.1);assert(p.angle>0);`);
run('running animates racket while contact geometry remains fixed',`newMatch();const p=players[0];cancelShot();p.swing=0;p.vx=180;p.vy=0;p.gait=0;const first=displayRacketPose(p);p.gait=Math.PI/2;const next=displayRacketPose(p);assert(Math.hypot(first.x-next.x,first.y-next.y)>5);assert(next.z>first.z);assert.equal(Math.hypot(racketPose(p).x-p.x,racketPose(p).y-p.y),40);`);
run('rally heat increases AI error pressure and resets next serve',`newMatch();const p=players[2];ball={x:p.x-40,y:p.y,z:45,vx:200,vy:0};hits=0;const calm=errorChance(p,.6);hits=50;assert(errorChance(p,.6)>calm+.01);assert.equal(rallyHeat(),1);setupServe();assert.equal(rallyHeat(),0);`);
run('ball seams rotate with travel and reverse spin with travel direction',`newMatch();const b={x:200,y:100,z:100,vx:100,vy:0,vz:0,last:1,bounces:1,power:.4};physics(b,.01,false);const spin=b.spin;assert(spin>0);b.vx=-100;physics(b,.01,false);assert(b.spin<spin);`);

run('gesture ink preserves curves after release, fades, and never recenters the pointer',`newMatch();state='play';scale=1;mouse={x:100,y:100};beginCharge('Mouse1',false);charge.samples=[{x:100,y:100,t:0}];updateSwipe(130,80,30);updateSwipe(160,110,60);updateSwipe(190,90,90);const stroke=activeStroke;assert.equal(stroke.points.length,4);assert.equal(stroke.points[1].y,80);assert.equal(stroke.points[2].y,110);releaseCharge('Mouse1');assert.equal(activeStroke,null);assert.equal(mouse.x,190);assert.equal(mouse.y,90);assert.equal(strokeOpacity(stroke,stroke.released+500),.82);assert(strokeOpacity(stroke,stroke.released+800)<.82);assert.equal(strokeOpacity(stroke,stroke.released+1100),0);cancelShot();`);

run('long strokes are stronger for drives and lobs and keep power while waiting for contact',`newMatch();state='play';scale=1;swipeSensitivity=80;for(const lob of [false,true]){const powers=[];for(const length of [30,120,270]){mouse={x:0,y:0};beginCharge(lob?'Mouse2':'Mouse1',lob);charge.samples=[{x:0,y:0,t:0}];updateSwipe(length,0,1000);powers.push(charge.power);const held=charge.power;advanceCharge(2);assert.equal(charge.power,held);cancelShot();}assert(powers[0]<.35);assert(powers[1]>powers[0]);assert(powers[2]>.85);}`);

run('AI spreads real placements across both receiver lanes, including the human',`newMatch();const p=players[2];p.x=750;p.y=140;players[0].x=180;players[0].y=365;players[1].x=260;players[1].y=140;let humanLane=0;for(let i=0;i<400;i++){const c=aiPlacement(p,i%4===0);humanLane+=c.targetY>250;rememberAIPlacement(p,c,i%4===0);}assert(humanLane>140&&humanLane<260);console.log('Human-side placements',humanLane,'/400');`);

run('groundstrokes use player-relative forehand/backhand and one color-matched quality label',`newMatch();const p=players[0];p.x=300;p.y=340;p.angle=0;assert.equal(shotFamily(false,.5,{x:340,y:360,z:40,bounces:1},p),'DRIVE');assert.equal(shotFamily(false,.5,{x:340,y:320,z:40,bounces:1},p),'BACKHAND');p.angle=Math.PI;assert.equal(shotFamily(false,.5,{x:260,y:360,z:40,bounces:1},p),'BACKHAND');assert.equal(shotFamily(false,1,{x:260,y:340,z:140,bounces:1},p),'DRIVE');assert.equal(shotFamily(true,1,{bounces:0},p),'LOB');assert.equal(shotFamily(true,.5,{bounces:1},p),'LOB');state='play';p.angle=0;p.cool=0;ball={x:340,y:340,z:35,vx:-200,vy:0,last:1,bounces:1};assert(hit(p,false,.75,{x:1,y:0,mouse:true},'LATE'));assert.equal(p.shotQuality,'LATE');assert.equal(p.shotFeedback,'DRIVE');assert.equal(p.shotTint,shotColor(.75));assert.equal(p.impactFlash.color,p.shotTint);assert.equal(p.shotUntil,clock+.5);assert.equal(tr('BACKHAND'),language==='es'?'REVÉS':'BACKHAND');`);

run('games keep physical ends fixed, preserving teams and service order',`defaultMatchGames=9;newMatch();const identities=players.map(p=>p.team);for(let game=1;game<=5;game++){state='play';const winner=game%2;score=winner?[0,3]:[3,0];point(winner,'DOUBLE BOUNCE');assert.equal(pendingEndChange,false);assert.equal(lastResult.previousGames[0]+lastResult.previousGames[1],game-1);continuePoint();assert.equal(endsChanged,false);assert.equal(serverIndex,serviceOrder[(1+game)%4]);assert.deepEqual(players.map(p=>p.team),identities);for(const p of players){assert.equal(side(p.x),p.team);const c=shotPlan(p,true,.4,{x:courtSide(p.team)?-1:1,y:0});assert.equal(side(c.targetX),1-p.team);}const flag=endsChanged;setupServe(2);assert.equal(endsChanged,flag);}defaultMatchGames=3;newMatch();assert.equal(endsChanged,false);`);
run('swapped ends keep legal bounces, net faults and AI targets on correct teams',`newMatch();endsChanged=true;resetPlayers();for(const p of players){p.x=courtSide(p.team)?800:200;const target=aiPlacement(p,false);assert.equal(side(target.targetX),1-p.team);}state='play';ball={x:200,y:130,z:.1,vx:0,vy:0,vz:-30,last:0,bounces:0,legalBounce:false};physics(ball,.02);assert.equal(state,'play');assert(ball.legalBounce);ball={x:505,y:250,z:10,vx:-400,vy:0,vz:0,last:0,bounces:0};physics(ball,.02);assert.equal(score[1],1);newMatch();`);
run('first fault coasts without awarding a point or changing server',`newMatch();state='play';const serving=serverIndex;ball={x:400,y:200,z:50,vx:120,vy:40,vz:50,last:players[serving].team,bounces:0,serve:true};serveFault('NET');const x=ball.x;tick(.1);assert.equal(state,'fault');assert.notEqual(ball.x,x);assert.deepEqual(score,[0,0]);for(let i=0;i<220;i++)tick(1/120);assert.equal(state,'serve');assert.equal(serveAttempt,2);assert.equal(serverIndex,serving);`);
run('full match uses golden points, six-game sets, seven-point win-by-two tiebreak and two sets to win',`defaultMatchGames=0;newMatch();assert.equal(matchGames,0);games=[5,4];score=[3,3];assert.equal(awardPoint(0),'SET');assert.deepEqual(sets,[1,0]);assert.deepEqual(completedSets,[[6,4]]);assert.deepEqual(games,[0,0]);games=[5,6];score=[3,0];assert.equal(awardPoint(0),'GAME');assert(tiebreak);score=[6,6];assert.equal(awardPoint(0),'POINT');assert.equal(awardPoint(0),'MATCH');assert.deepEqual(sets,[2,0]);assert.deepEqual(completedSets[1],[7,6]);defaultMatchGames=3;newMatch();`);

run('finisher charges on five nonconsecutive perfect contacts; sixth spends and promotes any tier',`for(const inputPower of [.2,.5,.75,1]){newMatch();state='play';let p=players[0];p.x=300;p.y=340;p.angle=0;const contact=(grade,q=inputPower)=>{p.cool=0;ball={x:340,y:340,z:35,vx:-200,vy:0,last:1,bounces:1,glassTouches:0};assert(hit(p,false,q,{x:1,y:0,mouse:true},grade));};for(let i=0;i<5;i++){contact('PERFECT');assert.equal(p.finisherCharge,i+1);assert.equal(ball.finisher,false);contact('LATE');assert.equal(p.finisherCharge,i+1);}assert.equal(p.finisherCharge,5);setupServe();assert.equal(players[0].finisherCharge,5);p=players[0];p.x=300;p.y=340;p.angle=0;state='play';contact('PERFECT');assert.equal(p.finisherCharge,0);assert(ball.finisher);assert(ball.power>=.92);assert.equal(ball.shotColor,'#ff645f');assert.equal(p.shotFeedback,'FINISHER');assert.equal(state,'play');assert.equal(stats.points,0);const testBall={...ball};let outcome=null;for(let i=0;i<700&&!outcome&&!testBall.bounces;i++)outcome=physics(testBall,1/240,false);assert.equal(outcome,null);assert.equal(testBall.bounces,1);contact('PERFECT');assert.equal(p.finisherCharge,1);newMatch();assert(players.every(p=>p.finisherCharge===0));}`);
run('finisher is independent per player, misses do not charge, practice does not arm it',`newMatch();state='play';const p=players[0];p.finisherCharge=4;p.cool=1;assert.equal(hit(p,false,.5,{x:1,y:0},'PERFECT'),false);assert.equal(p.finisherCharge,4);assert.equal(players[1].finisherCharge,0);const ai=players[1];for(let i=0;i<5;i++)assert.equal(chargeFinisher(ai,'PERFECT'),false);assert.equal(ai.finisherCharge,5);assert.equal(chargeFinisher(ai,'EARLY'),false);assert.equal(ai.finisherCharge,5);assert(chargeFinisher(ai,'PERFECT'));assert.equal(ai.finisherCharge,0);globalThis.Practice={active:true};assert.equal(chargeFinisher(p,'PERFECT'),false);assert.equal(p.finisherCharge,4);delete globalThis.Practice;`);
run('bounce ripple is smaller while impact rings retain their size',`effects=[];const b={x:700,y:200,z:1,vx:100,vy:0,vz:-100,last:0,bounces:0};physics(b,.02,true);assert(effects.some(e=>e.size===.55));ring(100,100,'#fff');assert.equal(effects.at(-1).size,1);`);
run('canvas sizes follow layout changes without stretching and ignore hidden zero sizes',`const original=canvas.getBoundingClientRect;for(const [width,height] of [[1366,663],[844,330],[1024,550],[900.5,450.25]]){canvas.getBoundingClientRect=()=>({width,height});resize();assert.equal(cw,width);assert.equal(ch,height);assert.equal(canvas.width,Math.round(width));assert.equal(canvas.height,Math.round(height));assert(scale>0);assert(Math.abs((1000*scale)/(500*scale)-2)<1e-9);}canvas.getBoundingClientRect=()=>({width:0,height:0});const before=cw;resize();assert.equal(cw,before);canvas.getBoundingClientRect=original;resize();`);
run('compact snapshots preserve identity and hydrate artwork without resending it',`network.active=true;network.isHost=true;network.session={id:'host'};network.slot=0;network.room={host:'host',members:[{id:'host',slot:0,name:'Host Name',online:true}]};newMatch();const art=roster[0];players[0].appearance=art;players[0].displayName='Host Name';const s=JSON.parse(networkJSON(network.snapshot()));assert.equal(s.players[0].appearanceId,0);assert.equal(s.players[0].appearance,undefined);assert.equal(s.players[0].displayName,'Host Name');network.isHost=false;network.lastSeq=0;network.started=true;network.receiveSnapshot(s);assert.equal(players[0].appearance,art);assert.equal(players[0].displayName,'Host Name');network.active=false;`);
run('direct connection measures its own RTT and sends already encoded snapshots unchanged',`let sent;const channel={readyState:'open',bufferedAmount:0,send:v=>sent=v},peer={channel,pc:{}};network.peers.set('host',peer);network.channel('host',peer.pc,channel);channel.onmessage({data:JSON.stringify({type:'ping',at:123})});assert.deepEqual(JSON.parse(sent),{type:'pong',at:123});network.directRtt=null;channel.onmessage({data:JSON.stringify({type:'pong',at:performance.now()-24})});assert(network.directRtt>=24&&network.directRtt<30);network.send(peer,'{"type":"snapshot"}');assert.equal(sent,'{"type":"snapshot"}');channel.bufferedAmount=13000;assert.equal(network.send(peer,{}),false);network.peers.clear();`);
run('Casual reaches incoming ground shot without firing and character stats affect movement',`network.active=false;globalThis.matchControlMode='casual';newMatch();state='play';const p=players[0];Object.assign(p,{x:170,y:355,swing:0});ball={x:420,y:355,z:60,vx:-180,vy:0,vz:60,last:1,bounces:0,legalBounce:false};let closest=Infinity;for(let i=0;i<120&&state==='play';i++){tick(1/120);closest=Math.min(closest,Math.hypot(ball.x-p.x,ball.y-p.y));}assert(closest<65,'contact distance '+closest);assert.equal(ball.last,1,'must still swipe to hit');const slow=humanMoveSpeed(p);globalThis.Career={attributes:()=>({speed:5,stamina:5})};assert(humanMoveSpeed(p)>slow);delete globalThis.Career;globalThis.matchControlMode='competitive';`);
run('elite AI levels 6 through 15 scale monotonically and stay finite',`newMatch();const p=players[2];let speed=0,reaction=1;for(let n=6;n<=15;n++){p.aiLevel=n;const l=levelOf(p);assert(l.speed>speed);assert(l.reaction<reaction);assert(Number.isFinite(errorChance(p,.8)));speed=l.speed;reaction=l.reaction;}p.aiLevel='club';assert(Number.isFinite(errorChance(p,.8)));`);
run('online snapshots carry the locked control mode',`globalThis.matchControlMode='casual';network.active=true;network.isHost=true;const s=network.snapshot();assert.equal(s.controlMode,'casual');network.isHost=false;network.started=true;network.receiveSnapshot({...s,seq:network.lastSeq+100});assert.equal(globalThis.matchControlMode,'casual');network.active=false;globalThis.matchControlMode='competitive';`);
run('Casual tracks wall rebounds and lobs on either court end',`network.active=false;globalThis.matchControlMode='casual';for(const end of [false,true])for(const kind of ['wall','lob']){newMatch();endsChanged=end;state='play';const p=players[0];Object.assign(p,{x:end?830:170,y:355,swing:0,autoShot:-1});const sign=end?-1:1;ball={x:end?920:80,y:355,z:kind==='lob'?240:55,vx:-sign*(kind==='lob'?35:130),vy:0,vz:kind==='lob'?-25:75,last:1,bounces:kind==='wall'?1:0,legalBounce:kind==='wall'};let closest=Infinity;for(let i=0;i<400;i++){clock+=.01;const a=casualAxes(p);p.x+=a.x*humanMoveSpeed(p)*.01;p.y+=a.y*humanMoveSpeed(p)*.01;if(ball.z>10&&ball.z<185)closest=Math.min(closest,Math.hypot(ball.x-p.x,ball.y-p.y));if(physics(ball,.01,false))break;}assert(closest<80,kind+' end '+end+' distance '+closest);}globalThis.matchControlMode='competitive';endsChanged=false;`);
run('Casual boost accelerates automatic movement, exhausts and recovers',`network.active=false;globalThis.matchControlMode='casual';newMatch();const p=players[0],base=humanMoveSpeed(p);updateCasualBoost(p,.5,true);assert(p.boosting);assert(humanMoveSpeed(p)>base*1.5);assert.equal(p.energy,.75);updateCasualBoost(p,2,true);assert(p.boostExhausted);assert(!p.boosting);updateCasualBoost(p,1,true);assert(!p.boosting);updateCasualBoost(p,1,false);assert(p.energy>0);updateCasualBoost(p,.1,true);assert(p.boosting);globalThis.matchControlMode='competitive';`);
run('mode speed defaults and bounded slider',`network.active=false;speedMode=null;applyModeSpeed('casual');assert.equal(gameSpeed,70);applyModeSpeed('competitive');assert.equal(gameSpeed,100);$('#game-speed').oninput({target:{value:'25'}});assert.equal(gameSpeed,25);$('#game-speed').oninput({target:{value:'200'}});assert.equal(gameSpeed,150);gameSpeed=100;`);
run('Casual AI is safer but still mixes overhead attack powers and spin',`newMatch();const p=players[2];p.aiLevel=2;p.x=620;p.y=145;ball={x:600,y:145,z:150,vx:30,vy:0,vz:-50,last:0,bounces:0,shotKind:'LOB'};globalThis.matchControlMode='competitive';const before=errorChance(p,.5);globalThis.matchControlMode='casual';assert(errorChance(p,.5)<before);const types=new Set();for(let i=0;i<300;i++){const c=aiChoice(p);if(c.attack)types.add(c.overheadPower);}assert.equal(types.size,3);globalThis.matchControlMode='competitive';`);
run('contact slowdown is reachable, bounded, once per shot and clears on hit',`network.active=false;globalThis.matchControlMode='casual';newMatch();state='play';pendingShot=null;charge={source:'Mouse1',gesture:true};const p=players[0];Object.assign(p,{x:250,y:330,angle:0,cool:0});ball={x:300,y:330,z:30,vx:-200,vy:0,vz:20,last:1,bounces:1,legalBounce:true};updateContactAssist(.01);assert.equal(ball.contactPace,.12);const until=ball.contactUntil;clock=until+.01;updateContactAssist(.01);assert.equal(ball.contactPace,1);assert.equal(ball.contactUntil,until);updateContactAssist(.01);assert.equal(ball.contactUntil,until);assert(hit(p,false,.5,{x:1,y:0},'PERFECT'));assert.equal(ball.contactPace,1);assert.equal(ball.contactUsed,undefined);assert(ball.impactPerfect);assert(p.impactFlash.perfect);assert(!effects.some(e=>e.x===p.impactFlash.x&&e.y===p.impactFlash.y));globalThis.matchControlMode='competitive';`);
run('contact assist never stops unreachable lobs or illegal service volleys',`newMatch();state='play';pendingShot=null;charge={source:'Mouse1',gesture:true};const p=players[0];Object.assign(p,{x:250,y:330,angle:0,cool:0});for(const extra of [{x:800},{z:250},{serve:true,bounces:0}]){ball={x:300,y:330,z:30,vx:-200,vy:0,vz:20,last:1,bounces:1,...extra};updateContactAssist(.01);assert.equal(ball.contactUsed,undefined);assert.equal(ball.contactPace,1);}`);
run('3x physics keeps collisions finite and awards a point once',`newMatch();state='play';hits=50;gameSpeed=150;ball={x:650,y:330,z:25,vx:-1400,vy:0,vz:-10,last:1,bounces:0,power:.9,shotKind:'DRIVE'};for(let i=0;i<100&&state==='play';i++)physics(ball,1/120);assert.equal(stats.points,1);assert(Number.isFinite(ball.x)&&Number.isFinite(ball.z));gameSpeed=100;`);

run('pass-through preserves assist for an intentional wall return',`network.active=false;newMatch();state='play';charge=null;pendingShot=null;const p=players[0];Object.assign(p,{x:250,y:330,angle:0,cool:0});ball={x:300,y:330,z:30,vx:-200,vy:0,vz:20,last:1,bounces:1,legalBounce:true};updateContactAssist(.01);assert.equal(ball.contactPace,1);assert(!ball.contactUsed);ball.glassTouches=1;ball.vx=200;charge={source:'Mouse1',gesture:true};updateContactAssist(.01);assert.equal(ball.contactPace,.12);assert(ball.contactUsed);const end=ball.contactUntil;charge=null;updateContactAssist(.01);assert(ball.contactUntil<=clock+.061);clock+=.07;updateContactAssist(.01);assert.equal(ball.contactPace,1);charge={source:'Mouse1'};updateContactAssist(.01);assert.equal(ball.contactPace,1);charge=null;`);
run('remote human gesture gates slowdown independently of host input',`network.active=true;network.isHost=true;network.slot=0;state='play';const p=players[2];Object.assign(p,{human:true,x:750,y:145,angle:Math.PI,cool:0,netCharge:null,netPending:null});ball={x:700,y:145,z:30,vx:200,vy:0,vz:20,last:0,bounces:1,legalBounce:true};charge={source:'Mouse1'};updateContactAssist(.01);assert.equal(ball.contactPace,1);p.netCharge={gesture:true,power:.15};updateContactAssist(.01);assert.equal(ball.contactPace,.12);assert.equal(ball.contactOwner,2);network.active=false;charge=null;p.netCharge=null;`);

run('selected delays apply to first faults and point breaks, and Continue advances once', `
 newMatch();
 const faultControl = $('#serve-delay'), pointControl = $('#point-delay');
 faultControl.value = '5'; faultControl.onchange();
 pointControl.value = '10'; pointControl.onchange();
 launchServe(); serveFault('NET'); tick(4);
 assert.equal(state,'fault'); tick(1.01); assert.equal(serveAttempt,2);
 launchServe(); serveFault('NET'); assert.equal(pointRemaining,10);
 assert.equal($('#point-advance-hint').textContent,'CLICK TO CONTINUE');
 assert.equal(pointCountdown(),'NEXT SERVE · 10');
 continuePoint(); continuePoint(); assert.equal(state,'serve'); assert.equal(stats.points,1);
 faultControl.value='1.8'; faultControl.onchange(); pointControl.value='4'; pointControl.onchange();
`);
run('online skins follow each member and survive snapshot, remapped slots, old clients and invalid inputs',`
 const oldSetup=globalThis.MatchSetup, oldSkins=globalThis.PadelSkins;
 globalThis.PadelSkins={equipped:id=>id===10?1:0,tier:(id,n)=>Number.isInteger(id)&&Number.isInteger(n)&&n>=0&&n<=3?n:0};
 globalThis.MatchSetup={online:{ids:[11,10,8,7]}};
 network.isHost=true;network.active=true;network.slot=0;network.session={id:'host'};
 network.room={host:'host',members:[{id:'host',slot:0,online:true},{id:'guest',slot:1,online:true}]};network.received={};network.acks={};
 newMatch();for(let slot=0;slot<4;slot++)players[slot].appearance={id:MatchSetup.online.ids[slot]};
 assert.equal(network.skinForSlot(1,undefined),0);
 network.acceptInput('guest',{seq:1,skin:{id:10,tier:3}});network.applyRoster();
 assert.equal(players[1].skinTier,3);assert.equal(network.snapshot().players[1].skinTier,3);
 assert.equal(network.lobbyOutfits()[1].tier,3);assert.equal(network.skinForSlot(1,7),0);
 network.acceptInput('guest',{seq:2,skin:{id:10,tier:4}});assert.equal(network.skinForSlot(1,10),0);
 network.acceptInput('guest',{seq:3});assert.equal(network.skinForSlot(1,10),0);
 network.room.members[1].slot=2;assert.equal(network.skinForSlot(1,10),1);
 network.isHost=false;network.slot=2;network.lobbySkins=[{id:11,tier:2}];assert.equal(network.skinForSlot(0,11),2);assert.equal(network.skinForSlot(0,10),0);
 network.active=false;globalThis.PadelSkins=oldSkins;globalThis.MatchSetup=oldSetup;
`);

run('short-lob depth and all three playable smash trajectories on either end',`newMatch();for(const team of [0,1]){let p=players.find(p=>p.team===team),dir=courtSide(team)?-1:1;for(const [depth,expected] of [[100,true],[125,true],[140,false]]){assert.equal(shortLob({shotKind:'LOB',x:500+dir*depth,y:250,z:150,vx:0,vz:0,last:team}),expected);}for(const [roll,wanted] of [[.1,'POR TRES'],[.5,'POR CUATRO'],[.9,'TRAÍDA']]){state='play';ball={x:500-dir*60,y:250,z:150,last:team,power:.95,bounces:0,shotKind:'SMASH'};Object.assign(ball,punishLob(p,{y:.6},roll));for(let i=0;i<700&&state==='play';i++)physics(ball,1/120);assert(notice.includes(wanted),notice);}}`);

run('human red exit odds and angled or straight trajectories for volleys and smashes',`newMatch();let exits=0,total=0;for(const team of [0,1]){const p=players.find(p=>p.team===team),dir=courtSide(team)?-1:1;for(const [family,z] of [['VOLLEY',55],['SMASH',135]])for(const y of [-.55,0,.55])for(let i=0;i<100;i++){total++;if(i/100>=redExitChance(.95,false))continue;state='play';ball={x:500-dir*65,y:225,z,last:team,power:.95,bounces:0};Object.assign(ball,humanExitShot(p,{x:dir,y},family));for(let j=0;j<500&&state==='play';j++)physics(ball,1/120);assert(notice.includes(y?'POR TRES':'POR CUATRO'),notice);exits++;}}assert.equal(exits/total,.8);assert(redExitChance(1,true)>redExitChance(.85,false));`);

