run('each slot sees its own half near and swipe/movement follow screen axes',`newMatch();network.active=true;for(const slot of [0,1,2,3]){network.slot=slot;for(const vertical of [false,true]){portraitMode=vertical;const p=players[slot],v=viewPoint(p.x,p.y),mid=viewPoint(500,250);assert(vertical?v.y>mid.y:v.x<mid.x);const dir=courtVector(vertical?0:1,vertical?-1:0);assert.equal(dir.x,p.team?-1:1);assert.equal(movementKey(vertical?'KeyW':'KeyD'),p.team?'KeyA':'KeyD');}}network.active=false;portraitMode=false;`);

