run('portrait full court bounds fit both ends inside the canvas',`const original=canvas.getBoundingClientRect;portraitMode=true;for(const [w,h] of [[390,751],[375,667],[430,839],[320,568]]){canvas.getBoundingClientRect=()=>({width:w,height:h});for(const n of [1,3,0]){defaultMatchGames=n;newMatch();const hud=n===1?60:82;for(const end of [false,true]){endsChanged=end;for(const x of [-50,1050])for(const y of [-50,550]){const q=viewPoint(x,y),v={x:ox+q.x*scale,y:oy+q.y*scale};assert(v.x>=3.9&&v.x<=w-3.9,JSON.stringify({w,h,v}));assert(v.y>=hud+3.9&&v.y<=h-3.9,JSON.stringify({w,h,v}));}}}}canvas.getBoundingClientRect=original;portraitMode=false;defaultMatchGames=3;newMatch();`);
